//#region src/commands/setup-verify.ts
const SETUP_VERIFY_FLAGS = { "client-id": "string" };
const SETUP_VERIFY_USAGE = `Usage
  maple setup verify --client-id=<Iv…>

  --client-id  The comment App's Client ID, starting Iv. Not the App ID.`;
const DEVICE_CODE_URL = "https://github.com/login/device/code";
async function setupVerify(flags, fetcher = globalThis.fetch) {
	const value = flags["client-id"];
	const clientId = typeof value === "string" ? value.trim() : "";
	if (clientId === "") return failed(SETUP_VERIFY_USAGE);
	let response;
	try {
		response = await fetcher(DEVICE_CODE_URL, {
			method: "POST",
			headers: { accept: "application/json" },
			body: new URLSearchParams({
				client_id: clientId,
				scope: ""
			})
		});
	} catch (error) {
		return failed(`Could not reach GitHub: ${String(error)}`);
	}
	return verdict(response.status, await answerOf(response), clientId);
}
function verdict(status, answer, clientId) {
	if (answer.device_code) return {
		output: `Device Flow is on for ${clientId}. Reviewers can sign in.`,
		exitCode: 0
	};
	if (answer.error === "device_flow_disabled") return failed(`Device Flow is off for ${clientId}, so every reviewer's sign-in will fail.\nFix: the App's settings → Identifying and authorizing users → Enable Device Flow. No reinstall is needed.`);
	if (status === 404 || answer.error === "incorrect_client_credentials") return failed(`GitHub has no App with the client id ${clientId}. Copy the Client ID (it starts with Iv), not the App ID.`);
	const said = answer.error ? `: ${answer.error}` : "";
	return failed(`GitHub answered ${String(status)}${said}.`);
}
async function answerOf(response) {
	try {
		return await response.json();
	} catch {
		return {};
	}
}
function failed(output) {
	return {
		output,
		exitCode: 1
	};
}
//#endregion
export { DEVICE_CODE_URL, SETUP_VERIFY_FLAGS, SETUP_VERIFY_USAGE, setupVerify };
